const crypto = require('crypto');
const b = $input.first().json.body || {};
const email = String(b.email || '').trim().toLowerCase();
const codigo = String(b.codigo || '').trim();
const valido = /^[^\s@']+@[^\s@']+\.[^\s@']+$/.test(email) && codigo.length >= 8 && codigo.length <= 80;
const hash = crypto.createHash('sha256').update(codigo).digest('hex');
const q = (v) => `'${String(v).replace(/'/g, "''")}'`;
const sql = valido
  ? `UPDATE acessos SET ultimo_login = now() WHERE email = ${q(email)} AND codigo_sha256 = ${q(hash)} AND ativo RETURNING email, cliente`
  : `SELECT NULL::text AS email WHERE false`;
return [{ json: { sql } }];

const crypto = require('crypto');
const SECRET = '<HMAC_SECRET_64_HEX>';
const row = $input.first().json || {};
if (!row.email) return [{ json: { ok: false, status: 401 } }];
const payload = Buffer.from(JSON.stringify({ e: row.email, x: Date.now() + 30 * 60 * 1000 })).toString('base64url');
const sig = crypto.createHmac('sha256', SECRET).update(payload).digest('base64url');
return [{ json: { ok: true, status: 200, session: `${payload}.${sig}`, cliente: row.cliente || '' } }];
